namespace ToneCustoms.ShellStudio.Materials;
public sealed class MaterialDefinition{public Guid Id{get;set;}=Guid.NewGuid();public string Name{get;set;}="New Material";public string BaseColor{get;set;}="";public string Normal{get;set;}="";public string Roughness{get;set;}="";public float TilingX{get;set;}=1;public float TilingY{get;set;}=1;public float OffsetX{get;set;}public float OffsetY{get;set;}public float Rotation{get;set;}public bool DoubleSided{get;set;}public bool CollisionMaterial{get;set;}}
public sealed record MaterialIssue(string Severity,string Message);
public static class MaterialValidator{static readonly string[] Allowed={".dds",".png",".tga"};public static IReadOnlyList<MaterialIssue> Validate(MaterialDefinition m){var r=new List<MaterialIssue>();Check(r,"Base Color",m.BaseColor);Check(r,"Normal",m.Normal,true);Check(r,"Roughness",m.Roughness,true);if(m.TilingX<=0||m.TilingY<=0)r.Add(new("ERROR","Texture tiling must be greater than zero."));return r;}static void Check(List<MaterialIssue> r,string label,string path,bool optional=false){if(string.IsNullOrWhiteSpace(path)){if(!optional)r.Add(new("ERROR",$"{label} texture is missing."));return;}var ext=Path.GetExtension(path).ToLowerInvariant();if(!Allowed.Contains(ext))r.Add(new("ERROR",$"{label}: unsupported texture format {ext}. Use DDS, PNG, or TGA."));if(ext==".jpg"||ext==".jpeg")r.Add(new("ERROR",$"{label}: JPG is not supported."));}}
